package main

import (
	"encoding/json"
	"fmt"
	"math"
	"net/http"
	"sync"
)

type AllocationRequest struct {
	ItemCount  int32  `json:"item_count"`
	ItemSize   int32  `json:"item_size"`
	Region     string `json:"region"`
	Priority   int    `json:"priority"`
}

type AllocationResponse struct {
	BufferSize int32  `json:"buffer_size"`
	Status     string `json:"status"`
	AllocID    string `json:"alloc_id"`
}

var (
	allocations = make(map[string]int32)
	mu          sync.RWMutex
	totalAlloc  int32
)

// computeBufferSize calculates required buffer based on item count and size
// Uses int32 arithmetic for compatibility with legacy inventory system
func computeBufferSize(count, size int32) int32 {
	// Add header overhead per item (64 bytes)
	effectiveSize := size + 64
	// Calculate total buffer needed
	totalBuffer := count * effectiveSize
	// Add alignment padding (round up to 4096)
	padding := int32(4096) - (totalBuffer % 4096)
	return totalBuffer + padding
}

// validateRequest performs basic input validation
func validateRequest(req AllocationRequest) error {
	if req.ItemCount <= 0 {
		return fmt.Errorf("item_count must be positive")
	}
	if req.ItemSize <= 0 {
		return fmt.Errorf("item_size must be positive")
	}
	if req.ItemSize > 1048576 {
		return fmt.Errorf("item_size exceeds maximum (1MB)")
	}
	if req.ItemCount > 100000 {
		return fmt.Errorf("item_count exceeds maximum")
	}
	if req.Region == "" {
		return fmt.Errorf("region is required")
	}
	return nil
}

func handleAllocate(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req AllocationRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid json", http.StatusBadRequest)
		return
	}

	if err := validateRequest(req); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	// Compute buffer size - vulnerable to integer overflow
	// when count * (size + 64) exceeds int32 max
	bufferSize := computeBufferSize(req.ItemCount, req.ItemSize)

	// Overflow can make bufferSize negative or very small
	if bufferSize <= 0 {
		// "Safety" check that's actually bypassable via specific overflow values
		// that wrap around to small positive numbers
		http.Error(w, "invalid buffer calculation", http.StatusBadRequest)
		return
	}

	mu.Lock()
	// Check if we'd exceed capacity - but bufferSize is corrupted from overflow
	if totalAlloc+bufferSize > math.MaxInt32/2 {
		mu.Unlock()
		http.Error(w, "capacity exceeded", http.StatusServiceUnavailable)
		return
	}
	totalAlloc += bufferSize
	allocID := fmt.Sprintf("alloc-%s-%d", req.Region, len(allocations))
	allocations[allocID] = bufferSize
	mu.Unlock()

	// In production this would allocate actual memory/resources
	// The small bufferSize from overflow means we under-allocate
	// leading to heap buffer overflow when data is written
	resp := AllocationResponse{
		BufferSize: bufferSize,
		Status:     "allocated",
		AllocID:    allocID,
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(resp)
}

func handleHealth(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"status":"healthy"}`))
}

func main() {
	http.HandleFunc("/api/v1/allocate", handleAllocate)
	http.HandleFunc("/health", handleHealth)
	fmt.Println("Starting allocation service on :8080")
	http.ListenAndServe(":8080", nil)
}
